import { NextResponse } from "next/server";
import { prisma } from "src/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "src/lib/auth";

export async function GET() {
  const session = await getServerSession(authOptions);

  // Güvenlik: Sadece Admin ve Medewerker girebilir
  if (!session || (session.user.role !== "ADMIN" && session.user.role !== "MEDEWERKER")) {
    return NextResponse.json({ error: "Yetkisiz Erişim" }, { status: 403 });
  }

  // Tüm kullanıcıları ve görevlerini getir
  const users = await prisma.user.findMany({
    include: { scrumItems: true },
  });

  // İstatistikleri hesapla
  const stats = users.map((user) => {
    const total = user.scrumItems.length;
    const done = user.scrumItems.filter((i) => i.columnId === "done").length;
    return {
      id: user.id,
      name: user.name || "Anonim",
      email: user.email,
      role: user.role,
      percentage: total > 0 ? Math.round((done / total) * 100) : 0,
      taskCount: total,
    };
  });

  // İletişim mesajlarını getir
  const messages = await prisma.contact.findMany({
    orderBy: { createdAt: "desc" },
  });

  return NextResponse.json({ stats, messages });
}